/* UX flows. Persistence and authentication are provided only by SaiServices. */
const api = window.SaiServices;
const $ = selector => document.querySelector(selector);
let catalog = {opportunities:[],providers:[],experiences:[],interests:[],opportunityTypes:[]};
let user = null, savedItems = [], activeInterest = 'الكل', authMode = 'login', returnTo = 'home';
let pendingAction = null, catalogVersion = 0, accountVersion = 0, catalogReady = false;
let experienceDraft = {title:'',body:'',field:''};
const dialog = $('#detail-dialog');
const normal = value => String(value || '').normalize('NFKC').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').toLowerCase();
const paragraphs = text => String(text || '').split('\n\n').map(p=>`<p class="preserve-text">${esc(p)}</p>`).join('');
function safeURL(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:null;}catch{return null;}}
function external(value,label){const url=safeURL(value);return url?`<a class="button outline" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('arrow')}</a>`:'<p class="muted">الرابط الرسمي غير متاح حاليًا.</p>';}
function tags(values){return (values || []).map(v=>`<span class="badge">${esc(v)}</span>`).join('');}
function status(selector,text,error=false){const el=$(selector);if(!el)return;el.hidden=!text;el.textContent=text;el.classList.toggle('is-error',error);}
function show(title,body,wide=false){dialog.classList.toggle('contribution-dialog',wide);$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!dialog.open)dialog.showModal();}
function notice(text){status('#toast',text);clearTimeout(notice.timer);notice.timer=setTimeout(()=>status('#toast',''),3500);}
function isSaved(kind,id){return savedItems.some(s=>s.kind===kind&&s.id===id);}
function saveButton(kind,item){const saved=isSaved(kind,item.id);return `<button type="button" class="icon-button save-button ${saved?'saved':''}" data-save="${esc(item.id)}" data-kind="${kind}" aria-label="${saved?'إلغاء حفظ':'حفظ'} ${esc(item.title||item.name)}" aria-pressed="${saved}">${icon('bookmark')}</button>`;}
function opportunityCard(o){return `<article class="card"><div class="card-top"><span class="category-icon ${esc(o.color||'')}">${icon(o.icon||'compass')}</span>${saveButton('opportunity',o)}</div><div class="opportunity-tags">${tags(o.fields)}</div><h3>${esc(o.title)}</h3><p>${esc(o.description||o.sourceName||'')}</p>${o.sourceName?`<p class="muted">${esc(o.sourceName)}</p>`:''}<div class="card-meta"><span>${esc(o.mode||'')}</span><span>${esc(o.type||'')}</span></div><div class="card-bottom"><span>${esc(o.deadline||'')}</span><button class="text-link" data-detail="${esc(o.id)}">عرض المنشور ${icon('arrow')}</button></div></article>`;}
function providerCard(p){return `<article class="provider-card"><span class="provider-monogram">${esc(p.mark||(p.name||'').slice(0,1))}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.description||'')}</p><div class="opportunity-tags">${tags(p.fields)}</div><div class="provider-actions"><button class="text-link" data-provider="${esc(p.id)}">استكشف الجهة ${icon('arrow')}</button>${saveButton('provider',p)}</div></div></article>`;}
function renderOpportunities(){
 const words=normal($('#opportunity-search').value).trim().split(/\s+/).filter(Boolean);
 const items=catalog.opportunities.filter(o=>{const fields=o.fields||[];const text=normal([o.title,o.sourceName,o.description,o.originalText,o.audience,...fields,o.type,o.mode].flatMap(value=>[value,window.SaiI18n?.t(value||'')||value]).join(' '));return (activeInterest==='الكل'||fields.includes(activeInterest))&&(!$('#opportunity-type').value||o.type===$('#opportunity-type').value)&&(!$('#opportunity-mode').value||o.mode===$('#opportunity-mode').value)&&words.every(w=>text.includes(w));});
 $('#opportunity-grid').innerHTML=items.map(opportunityCard).join('');
 $('#empty-opportunities').hidden=items.length>0;
 document.querySelectorAll('[data-interest]').forEach(el=>{el.classList.toggle('active',el.dataset.interest===activeInterest);el.setAttribute('aria-pressed',String(el.dataset.interest===activeInterest));});
}
function renderProviders(){const q=normal($('#provider-search').value);const items=catalog.providers.filter(p=>normal([p.name,p.description,...(p.fields||[]),...(p.contentTypes||[])].flatMap(value=>[value,window.SaiI18n?.t(value||'')||value]).join(' ')).includes(q));$('#provider-grid').innerHTML=items.map(providerCard).join('');status('#provider-state',items.length?'':'لا توجد جهات مطابقة. جرّب كلمة أقصر أو امسح البحث.');}
function renderExperiences(){$('#experience-grid').innerHTML=catalog.experiences.map(e=>`<article class="card experience-card"><div class="quote" aria-hidden="true">“</div><h3>${esc(e.title||'تجربة طالب')}</h3><p>${esc(e.description||String(e.body||'').slice(0,150))}</p><div class="experience-author"><span class="avatar">${esc(e.initial||'س')}</span><span>${esc(e.field||'تجربة طالب')}${e.publishedAt?' · '+esc(e.publishedAt):''}</span></div><button class="text-link" data-experience="${esc(e.id)}">اقرأ التجربة ${icon('arrow')}</button></article>`).join('');status('#experience-state',catalog.experiences.length?'':'لم تُنشر تجارب بعد. شارك تجربتك لتكون إحدى البدايات.');}
async function loadCatalog(){
 const version=++catalogVersion;
 ['opportunity','provider','experience'].forEach(k=>status('#'+k+'-state','جارٍ تحميل المحتوى…'));
 try{const result=await api.catalog();if(version!==catalogVersion)return;
  for(const key of ['opportunities','providers','experiences'])if(!Array.isArray(result?.[key]))throw new Error('تعذّر عرض المحتوى.');
  catalog={...catalog,...result};catalogReady=true;
  for(const key of ['opportunities','providers','experiences'])catalog[key]=catalog[key].filter(item=>!item.status||item.status==='published');
  catalog.interests=['الكل',...new Set([...(catalog.interests||[]).filter(x=>x!=='الكل'),...catalog.opportunities.flatMap(o=>o.fields||[])])];
  $('#interest-chips').innerHTML=catalog.interests.map(t=>`<button class="chip" data-interest="${esc(t)}" aria-pressed="false">${esc(t==='الكل'?'جميع المجالات':t)}</button>`).join('');
  for(const [id,key,label] of [['opportunity-type','type','جميع الأنواع'],['opportunity-mode','mode','جميع الطرق']]){const select=$('#'+id),value=select.value;select.replaceChildren(new Option(label,''));[...new Set(catalog.opportunities.map(o=>o[key]).filter(Boolean))].forEach(v=>select.add(new Option(v,v)));select.value=value;if(select.selectedIndex<0)select.value='';}
  ['opportunity','provider','experience'].forEach(k=>status('#'+k+'-state',''));
  renderOpportunities();renderProviders();renderExperiences();
 }catch{if(version!==catalogVersion)return;$('#empty-opportunities').hidden=true;['opportunity','provider','experience'].forEach(k=>{$('#'+k+'-state').innerHTML='<div class="empty">تعذّر تحميل المحتوى. <button class="text-link" data-action="retry">إعادة المحاولة</button></div>';});}
}
function requireUser(action){if(user)return true;pendingAction=action;returnTo=location.hash.slice(1)||'home';location.hash='login';notice('سجّل دخولك للمتابعة، ثم نعيدك إلى ما اخترته.');return false;}
function syncAccount(){document.querySelectorAll('[data-guest-only]').forEach(el=>el.hidden=!!user);$('#profile-link').hidden=!user;$('.profile-mini-avatar').textContent=(user?.name||'س').slice(0,1);$('#mobile-account-link').href=user?'#profile':'#login';$('#mobile-account-link').dataset.nav=user?'profile':'login';$('#mobile-account-label').textContent=user?'ملفي':'حسابي';$('#saved-count').textContent=savedItems.length;$('#saved-count').hidden=!savedItems.length;}
async function toggleSave(kind,id,button){if(!requireUser(()=>toggleSave(kind,id)))return;const version=accountVersion;const value=!isSaved(kind,id);if(button)button.disabled=true;try{await api.setSaved(kind,id,value);if(version!==accountVersion)return;savedItems=savedItems.filter(s=>!(s.kind===kind&&s.id===id));if(value)savedItems.push({kind,id});syncAccount();renderOpportunities();renderProviders();if(location.hash==='#saved')renderSaved();notice(value?'أضيفت إلى محفوظاتك.':'أزيلت من المحفوظات.');}catch(error){notice(error.message||'تعذّر تحديث المحفوظات. حاول مرة أخرى.');}finally{if(button)button.disabled=false;}}
function renderSaved(){const content=$('#saved-content');content.innerHTML=savedItems.length?`<div class="card-grid">${savedItems.map(s=>{const item=(s.kind==='provider'?catalog.providers:catalog.opportunities).find(x=>x.id===s.id);return item?(s.kind==='provider'?providerCard(item):opportunityCard(item)):`<article class="card"><h3>هذا المحتوى غير متاح الآن</h3><button class="text-link" data-save="${esc(s.id)}" data-kind="${esc(s.kind)}">إزالة من المحفوظات</button></article>`;}).join('')}</div>`:'<div class="empty"><p>لم تحفظ شيئًا بعد.</p><a class="text-link" href="#opportunities">استكشف الفرص</a></div>';}
async function loadSaved(){const version=accountVersion;$('#saved-content').innerHTML='<p role="status">جارٍ تحميل المحفوظات…</p>';try{const result=await api.saved();if(version!==accountVersion)return;savedItems=result;syncAccount();renderSaved();}catch{$('#saved-content').innerHTML='<div class="empty">تعذّر تحميل المحفوظات. <button class="text-link" data-action="reload-saved">إعادة المحاولة</button></div>';}}
function openOpportunity(id){const o=catalog.opportunities.find(x=>x.id===id);if(!o)return;show(o.title,`<div class="opportunity-tags">${tags(o.fields)}</div>${o.sourceName?`<p><strong>المصدر:</strong> ${esc(o.sourceName)}</p>`:''}${paragraphs(o.originalText||o.details||o.description)}${o.publishedAt?`<p>تاريخ النشر: ${esc(o.publishedAt)}</p>`:''}${o.deadline?`<p>الموعد: ${esc(o.deadline)}</p>`:''}${(o.attachments||[]).map(a=>external(a.url,a.name||'فتح المرفق')).join('')}<div class="detail-actions">${external(o.registrationUrl||o.sourceUrl,o.registrationUrl?'زيارة التسجيل':'فتح المصدر الأصلي')}<button class="text-link" data-save="${esc(o.id)}" data-kind="opportunity">حفظ الفرصة</button></div>`);}
function openProvider(id){const p=catalog.providers.find(x=>x.id===id);if(!p)return;show(p.name,`${paragraphs(p.details||p.description)}<div class="opportunity-tags">${tags(p.fields)}${tags(p.contentTypes)}</div><dl class="detail-facts"><div><dt>اللغة</dt><dd>${esc(p.language||'تحقق من الموقع الرسمي')}</dd></div><div><dt>التكلفة</dt><dd>${esc(p.cost||'تحقق من الموقع الرسمي')}</dd></div></dl><div class="detail-actions">${external(p.url,'زيارة الجهة')}<button class="text-link" data-save="${esc(p.id)}" data-kind="provider">حفظ الجهة</button></div>`);}
function contributionDialog(){if(!requireUser(contributionDialog))return;show('شارك تجربتك',`<form id="experience-form" class="platform-form"><p><strong>كيف بدأت؟</strong> ما التحدّي الذي واجهته؟ وما النصيحة التي تود مشاركتها؟</p><label for="experience-title">عنوان التجربة <span class="muted">(اختياري)</span></label><input id="experience-title" name="title" maxlength="120" value="${esc(experienceDraft.title)}"><label class="sr-only" for="experience-draft">نص التجربة</label><textarea id="experience-draft" name="body" rows="7" required minlength="30" maxlength="6000" placeholder="اكتب تجربتك هنا…">${esc(experienceDraft.body)}</textarea><label for="experience-field">المجال <span class="muted">(اختياري)</span></label><select id="experience-field" name="field"><option value="">اختر المجال</option>${catalog.interests.filter(x=>x!=='الكل').map(x=>`<option ${x===experienceDraft.field?'selected':''}>${esc(x)}</option>`).join('')}</select><label class="check-label"><input type="checkbox" required> أوافق على إرسال تجربتي للمراجعة قبل النشر.</label><p id="experience-feedback" class="form-feedback" role="status" hidden></p><button class="button" type="submit">إرسال للمراجعة</button></form>`,true);}
function setAuthMode(mode){authMode=mode;$('#login-form').reset();$('#password').type='password';$('#toggle-password').setAttribute('aria-pressed','false');$('#toggle-password').setAttribute('aria-label','إظهار كلمة المرور');$('#signup-name').hidden=mode!=='signup';$('#display-name').required=mode==='signup';$('#auth-password').hidden=mode==='reset';$('#password').required=mode!=='reset';$('#password').minLength=mode==='signup'?8:1;$('#password').autocomplete=mode==='signup'?'new-password':'current-password';$('#auth-title').textContent={login:'سعداء بعودتك.',signup:'ابدأ رحلتك مع سعي.',reset:'استعادة كلمة المرور'}[mode];$('#auth-submit').textContent={login:'تسجيل الدخول',signup:'إنشاء حساب',reset:'إرسال رابط الاستعادة'}[mode];$('#auth-mode-link').textContent=mode==='login'?'جديد في سعي؟ أنشئ حسابك':'لديك حساب؟ تسجيل الدخول';status('#auth-feedback','');}
async function formRequest(form,feedback,operation){const button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;form.setAttribute('aria-busy','true');status(feedback,'جارٍ تنفيذ طلبك…');try{await operation();}catch(error){status(feedback,error.message||'تعذّر إكمال الطلب. حاول مرة أخرى.',true);}finally{button.disabled=false;form.removeAttribute('aria-busy');}}
async function authenticate(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;await formRequest(form,'#auth-feedback',async()=>{const email=$('#email').value.trim(),password=$('#password').value;if(authMode==='reset'){await api.resetPassword(email);status('#auth-feedback','إذا كان البريد مسجّلًا، سيصلك رابط لاستعادة كلمة المرور.');return;}if(authMode==='signup'){if(!$('#display-name').value.trim())throw new Error('أدخل اسمك.');await api.signup({name:$('#display-name').value.trim(),email,password});setAuthMode('login');status('#auth-feedback','تم إنشاء الحساب. تحقّق من بريدك الإلكتروني، ثم سجّل الدخول.');return;}const result=await api.login({email,password});if(!result?.id)throw new Error('تعذّر التحقق من تسجيل الدخول.');user=result;accountVersion++;try{savedItems=await api.saved();}catch{savedItems=[];}syncAccount();const next=pendingAction;pendingAction=null;location.hash=returnTo==='login'?'home':returnTo;setTimeout(()=>next?.(),0);});$('#password').value='';}
function input(label,name,value='',type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" maxlength="200"></label>`;}
async function loadProfile(){const version=accountVersion;$('#profile-content').innerHTML='<p role="status">جارٍ تحميل ملفك…</p>';try{const [p,experiences]=await Promise.all([api.profile(),api.myExperiences()]);if(version!==accountVersion)return;$('#profile-content').innerHTML=`<div class="profile-layout"><aside class="profile-summary"><div class="profile-avatar">${esc((p.name||user.name||'س').slice(0,1))}</div><h2>${esc(p.name||user.name||'ملفي')}</h2><a class="button outline full" href="#saved">محفوظاتي</a>${user.role==='admin'?'<a class="text-link" href="#admin">إدارة المحتوى</a>':''}</aside><div class="profile-content"><section class="profile-panel"><h2>بياناتي</h2><form id="profile-form" class="platform-form">${input('الاسم','name',p.name||user.name)}${input('اهتماماتي (افصل بينها بفاصلة)','interests',(p.interests||[]).join('، '))}<p class="form-feedback" id="profile-feedback" role="status" hidden></p><button type="submit" class="button">حفظ التعديلات</button></form></section><section class="profile-panel"><h2>تجاربي</h2>${experiences.length?experiences.map(e=>`<article class="profile-record"><span class="badge">${esc({pending:'قيد المراجعة',published:'منشورة',rejected:'تحتاج تعديلًا'}[e.status]||'قيد المراجعة')}</span><h3>${esc(e.title||'تجربتي')}</h3><p>${esc(e.body||'')}</p></article>`).join(''):'<p class="muted">لم ترسل تجربة بعد.</p>'}<button class="text-link" data-action="contribute">شارك تجربتك</button></section></div></div>`;$('#profile-form [name="name"]').required=true;}catch{$('#profile-content').innerHTML='<div class="empty">تعذّر تحميل ملفك. <button class="text-link" data-action="reload-profile">إعادة المحاولة</button></div>';}}
function renderAdmin(){if(user?.role!=='admin'){$('#admin-content').innerHTML='<p class="empty">هذه المساحة متاحة لمسؤول المحتوى فقط.</p>';return;}$('#admin-content').innerHTML=`<form id="content-form" class="platform-form content-form"><label>نوع المحتوى<select name="kind" id="content-kind"><option value="opportunity">فرصة</option><option value="provider">جهة تعلّم</option></select></label>${input('العنوان أو اسم الجهة','title')}${input('اسم المصدر','sourceName')}<label>النص الأصلي أو نبذة الجهة<textarea name="originalText" rows="7" required maxlength="15000"></textarea></label>${input('رابط المصدر الرسمي','sourceUrl','','url')}${input('رابط صورة أو ملف من المصدر (اختياري)','attachmentUrl','','url')}${input('المجالات (اختياري، افصل بفاصلة)','fields')}${input('نوع الفرصة أو المحتوى (اختياري)','type')}${input('طريقة المشاركة (اختياري)','mode')}${input('الموعد كما ورد في الإعلان (اختياري)','deadline')}<label>الحالة<select name="status"><option value="draft">مسودة</option><option value="published">نشر</option></select></label><p id="content-feedback" class="form-feedback" role="status" hidden></p><button class="button" type="submit">حفظ المحتوى</button></form>`;$('#content-form [name="title"]').required=true;$('#content-form [name="sourceUrl"]').required=true;}
const titles={home:'مساحة لخطوتك القادمة',opportunities:'الفرص',learning:'جهات التعلم',experiences:'تجارب الطلاب',login:'تسجيل الدخول',profile:'ملفي',saved:'المحفوظات',admin:'إدارة المحتوى'};
function route(){let target=location.hash.slice(1)||'home';if(target==='main'){$('#main').focus();return;}if(!Object.hasOwn(titles,target)){target='home';history.replaceState(null,'','#home');}if(['profile','saved','admin'].includes(target)&&!user){returnTo=target;target='login';history.replaceState(null,'','#login');}document.querySelectorAll('[data-page]').forEach(p=>p.hidden=p.dataset.page!==target);document.querySelectorAll('[data-nav]').forEach(a=>{const selected=a.dataset.nav===target;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(dialog.open)dialog.close();document.title='سعي | '+titles[target];window.scrollTo({top:0,behavior:'instant'});const heading=$(`[data-page="${target}"] h1`);if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}if(target==='saved')loadSaved();if(target==='profile')loadProfile();if(target==='admin')renderAdmin();}
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;const d=el.dataset;if(d.interest){activeInterest=d.interest;renderOpportunities();return;}if(d.save){await toggleSave(d.kind,d.save,el);return;}if(d.detail){openOpportunity(d.detail);return;}if(d.provider){openProvider(d.provider);return;}if(d.experience){const e=catalog.experiences.find(x=>x.id===d.experience);if(e)show(e.title,paragraphs(e.body));return;}switch(d.action){case 'retry':loadCatalog();break;case 'contribute':contributionDialog();break;case 'saved':location.hash='saved';break;case 'reload-saved':loadSaved();break;case 'reload-profile':loadProfile();break;case 'signup':setAuthMode(authMode==='login'?'signup':'login');break;case 'forgot':setAuthMode('reset');break;case 'opportunity-assistant':show('ساعدني أختار','<p>المساعد سيتوفر لاحقًا. يمكنك الآن استخدام البحث والفلاتر لاستكشاف الفرص.</p>');break;case 'logout':el.disabled=true;try{await api.logout();accountVersion++;user=null;savedItems=[];pendingAction=null;experienceDraft={title:'',body:'',field:''};$('#profile-content').replaceChildren();$('#saved-content').replaceChildren();syncAccount();renderOpportunities();renderProviders();location.hash='home';}catch(error){notice(error.message);}finally{el.disabled=false;}break;}});
document.addEventListener('input',event=>{if(event.target.closest('#experience-form'))experienceDraft=Object.fromEntries(new FormData($('#experience-form')));});
document.addEventListener('submit',async event=>{const form=event.target;if(!['experience-form','profile-form','content-form'].includes(form.id))return;event.preventDefault();if(!user||!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const split=value=>String(value||'').split(/[,،]/).map(s=>s.trim()).filter(Boolean);
 if(form.id==='experience-form'){if(values.body.trim().length<30){status('#experience-feedback','اكتب تجربة من 30 حرفًا على الأقل.',true);return;}await formRequest(form,'#experience-feedback',async()=>{await api.submitExperience({...values,body:values.body.trim()});experienceDraft={title:'',body:'',field:''};show('وصلتنا تجربتك','<p>تجربتك قيد المراجعة، وستظهر للعامة بعد اعتمادها.</p><a class="button outline" href="#profile">متابعة الحالة في ملفي</a>');});}
 if(form.id==='profile-form')await formRequest(form,'#profile-feedback',async()=>{if(!values.name.trim())throw new Error('أدخل اسمك.');await api.updateProfile({name:values.name.trim(),interests:split(values.interests)});status('#profile-feedback','تم حفظ تعديلاتك.');});
 if(form.id==='content-form'&&user.role==='admin')await formRequest(form,'#content-feedback',async()=>{if(!safeURL(values.sourceUrl)||(values.attachmentUrl&&!safeURL(values.attachmentUrl)))throw new Error('أدخل رابطًا يبدأ بـ https:// أو http://.');if(!values.title.trim()||!values.originalText.trim())throw new Error('أدخل العنوان والنص.');const {kind,...rest}=values;await api.addContent(kind,{...rest,fields:split(values.fields)});form.reset();status('#content-feedback','تم حفظ المحتوى.');await loadCatalog();});
});
$('#login-form').addEventListener('submit',authenticate);
$('#toggle-password').onclick=function(){const visible=$('#password').type==='password';$('#password').type=visible?'text':'password';this.setAttribute('aria-pressed',String(visible));this.setAttribute('aria-label',visible?'إخفاء كلمة المرور':'إظهار كلمة المرور');};
$('#close-dialog').onclick=()=>dialog.close();
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
$('#provider-search').addEventListener('input',renderProviders);
$('#opportunity-search').addEventListener('input',renderOpportunities);
['opportunity-type','opportunity-mode'].forEach(id=>$('#'+id).addEventListener('change',renderOpportunities));
$('.skip').onclick=event=>{event.preventDefault();$('#main').focus();};
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const dailySteps=['مو لازم تعرف الطريق كله؛ يكفي تكتشف اليوم شيئًا يثير فضولك.','قد تبدأ رحلتك من فكرة بسيطة تفتح لك بابًا لم تتوقعه.','تجارب الآخرين تلهمك، وخطوتك أنت تأخذ شكل اهتماماتك وطموحك.'];
$('#step-description').textContent=dailySteps[Math.floor(Math.random()*dailySteps.length)];
(async()=>{await loadCatalog();try{user=await api.session();if(user)savedItems=await api.saved();}catch{notice('تعذّر التحقق من الحساب. يمكنك متابعة التصفح والمحاولة مجددًا.');}syncAccount();if(catalogReady){renderOpportunities();renderProviders();}window.addEventListener('hashchange',route);route();})();
